'use strict';

/**
* Compute the Bessel function of the first kind of order one for a single-precision floating-point number.
*
* @module @stdlib/math-base-special-besselj1f
*
* @example
* var besselj1f = require( '@stdlib/math-base-special-besselj1f' );
*
* var v = besselj1f( 0.0 );
* // returns 0.0
*
* v = besselj1f( 1.0 );
* // returns ~0.440
*
* v = besselj1f( Infinity );
* // returns 0.0
*
* v = besselj1f( -Infinity );
* // returns 0.0
*
* v = besselj1f( NaN );
* // returns NaN
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
